<script setup lang="ts">
import {onMounted,reactive,ref} from 'vue';
import type {BrowseContext,AlgorithmSummary,Paged,VersionPage,ModelVersion,VersionDetail} from '../types/model-browse';
import {modelBrowseApi,shownValue} from '../api/model-browse';
import {useReadScope} from '../composables/useReadScope';
import PageHeader from '../components/PageHeader.vue';
import AlgorithmEditor from '../components/AlgorithmEditor.vue';
import ModelVersionDetails from '../components/ModelVersionDetails.vue';
const props=defineProps<{context:BrowseContext}>(),api=modelBrowseApi(props.context),reads=useReadScope(props.context);
const filters=reactive<Record<string,string|number>>({page:1,query:'',algorithm_type:'',industry:'',source_type:'',status:'',sort:'updated',...props.context.memory.algorithms});
const algorithms=ref<Paged<AlgorithmSummary>|null>(null),versions=ref<VersionPage|null>(null),detail=ref<VersionDetail|null>(null),drawer=ref(false),selected=ref(props.context.memory.selection?.algorithmId||''),versionPage=ref(props.context.memory.versionPage||1);
const editor=ref(false),editingId=ref(''),pending=ref(props.context.algorithmPending?.value);
function edit(id=''){closeDetail();editingId.value=id;editor.value=true}
function closeEditor(){editor.value=false;pending.value=props.context.algorithmPending?.value}
function saved(id:string){closeEditor();selected.value=id;props.context.memory.selection={algorithmId:id,versionId:''};versionPage.value=1;void loadAlgorithms();void loadVersions()}
function clearPending(){props.context.algorithmPending?.save(null);pending.value=null}
function loadAlgorithms(){props.context.memory.algorithms={...filters};return reads.run('algorithms',signal=>api.algorithms(filters,signal),value=>{algorithms.value=value})}
function search(){filters.page=1;void loadAlgorithms()}
function changeAlgorithmPage(value:number){filters.page=value;void loadAlgorithms()}
function changeVersionPage(value:number){versionPage.value=value;void loadVersions()}
function loadVersions(){if(!selected.value)return;props.context.memory.versionPage=versionPage.value;return reads.run('versions',signal=>api.versions(selected.value,versionPage.value,signal),value=>{versions.value=value})}
function choose(row:AlgorithmSummary){reads.cancel('detail');reads.cancel('versions');drawer.value=false;detail.value=null;versions.value=null;selected.value=row.id;versionPage.value=1;props.context.memory.selection={algorithmId:row.id,versionId:'',algorithmName:row.name};void loadVersions()}
function closeDetail(){reads.cancel('detail');drawer.value=false;detail.value=null}
function show(row:ModelVersion){closeDetail();drawer.value=true;props.context.memory.selection={algorithmId:selected.value,versionId:row.id,algorithmName:versions.value?.algorithm.name,versionName:row.version_name};void reads.run('detail',signal=>api.detail(selected.value,row.id,signal),value=>{detail.value=value})}
function reportVersion(row:ModelVersion){closeDetail();if(row.training_job_id)props.context.openReport?.({jobId:row.training_job_id,algorithmId:selected.value,versionId:row.id,returnPage:'assets'})}
function history(row:ModelVersion){closeDetail();props.context.openHistory({algorithmId:selected.value,versionId:row.id,algorithmName:versions.value?.algorithm.name,versionName:row.version_name})}
onMounted(()=>{void loadAlgorithms();if(selected.value)void loadVersions()});
</script>
<template><section class="catalog-preview model-assets" aria-label="模型资产与算法版本只读浏览">
 <PageHeader :title="context.algorithmManagement?'算法管理与模型版本':'模型资产与算法版本'" eyebrow="模型管理 / 版本浏览" description="按项目浏览版本身份、已有元数据与转换关系。" :badge="context.algorithmManagement?'正式管理':'只读浏览'" @back="context.returnToManagement"/>
 <div v-if="context.algorithmManagement" class="management-actions"><el-button type="primary" :disabled="!!pending" @click="edit()">新增本地算法</el-button><el-button :disabled="!selected||!!pending" @click="edit(selected)">算法详情 / 基本编辑</el-button><el-button @click="context.openLegacy()">原训练 / 回退 / 删除 / 发布</el-button><el-button v-if="context.openMaterials" @click="context.openMaterials()">素材库</el-button><el-button v-if="context.openTasks" @click="context.openTasks()">训练任务中心</el-button></div>
 <el-alert v-if="pending" title="上次写入结果待确认，已阻止重复提交。请到原管理核对，不能据此认定保存成功。" type="warning" :closable="false"/><el-button v-if="pending" @click="clearPending">我已在原管理核对，解除待确认</el-button>
 <div v-if="!context.algorithmManagement&&context.openTasks" class="management-actions"><el-button @click="context.openTasks()">训练任务中心</el-button></div>
 <form class="browse-filters" @submit.prevent="search"><el-input v-model="filters.query" aria-label="搜索算法" placeholder="搜索算法名称" clearable/><el-select v-for="[key,label] in [['algorithm_type','算法类型'],['industry','分类'],['source_type','来源'],['status','记录状态']]" :key="key" v-model="filters[key]" :aria-label="label" :placeholder="label"><el-option :label="'全部'+label" value=""/><el-option v-for="value in algorithms?.filter_options?.[key]||[]" :key="value" :label="value" :value="value"/></el-select><el-select v-model="filters.sort" aria-label="算法排序"><el-option label="最近更新" value="updated"/><el-option label="最近创建" value="created"/><el-option label="名称升序" value="name"/><el-option label="名称降序" value="name_desc"/></el-select><el-button native-type="submit" type="primary" :disabled="reads.busy.algorithms">查询</el-button><el-button :disabled="reads.busy.algorithms" @click="loadAlgorithms">刷新算法</el-button></form>
 <div class="browse-columns"><section class="browse-panel" aria-label="算法摘要列表" :aria-busy="reads.busy.algorithms"><header><h2>项目算法</h2><small>{{ context.projectId }}</small></header>
  <el-alert v-if="reads.errors.algorithms" :title="reads.errors.algorithms" type="error" :closable="false"/><el-skeleton v-else-if="!algorithms&&reads.busy.algorithms" :rows="6" animated/>
  <el-table v-else-if="algorithms" :data="algorithms.items" max-height="560" row-key="id" empty-text="暂无匹配算法"><el-table-column label="算法" min-width="140"><template #default="{row}"><el-button link type="primary" :aria-label="`选择算法${row.name}`" @click="choose(row)">{{ row.name }}</el-button><small class="browse-secondary">{{ row.algorithm_type||'类型未提供' }} · {{ row.source_type||'来源未提供' }}</small><small class="browse-secondary">{{ row.industry||'分类未提供' }} · {{ row.status||'状态未提供' }}</small></template></el-table-column><el-table-column label="版本" width="95"><template #default="{row}">{{ row.version_count??'未提供' }}<small class="browse-secondary">当前：{{ row.current_version?.version_name||row.current_version_id||'未提供指针' }}</small></template></el-table-column><el-table-column label="时间" min-width="100"><template #default="{row}"><small>{{ row.updated_at||row.created_at||'未提供' }}</small></template></el-table-column></el-table>
  <footer v-if="algorithms" class="preview-pagination"><span>共 {{ algorithms.total }} 个算法</span><el-pagination layout="prev, pager, next" :pager-count="5" :page-size="20" :total="algorithms.total" :current-page="algorithms.page" @current-change="changeAlgorithmPage"/></footer>
 </section><section class="browse-panel" aria-label="模型版本列表" :aria-busy="reads.busy.versions"><header><div><h2>{{ versions?.algorithm.name||'模型版本' }}</h2><small>选择算法后按需读取，不自动展开报告或评测。</small></div><el-button :disabled="!selected||reads.busy.versions" @click="loadVersions">刷新版本</el-button></header>
  <el-alert v-if="reads.errors.versions" :title="reads.errors.versions" type="error" :closable="false"/><el-skeleton v-else-if="!versions&&reads.busy.versions" :rows="6" animated/><el-empty v-else-if="!selected" description="尚未读取版本，请先选择算法"/>
  <el-table v-else-if="versions" :data="versions.items" max-height="560" row-key="id" empty-text="该算法没有已保存版本"><el-table-column label="版本 / 文件" min-width="160"><template #default="{row}"><strong>{{ row.version_name||row.id }}</strong><el-tag v-if="versions.algorithm.current_version_id===row.id" type="info" size="small">当前版本</el-tag><small class="browse-secondary">{{ row.id }}</small><small class="browse-secondary">{{ row.framework||'框架未提供' }} · {{ row.model_file?.file_name||'文件名未提供' }}</small><small class="browse-secondary">{{ row.finished_at||row.created_at||'时间未提供' }}</small></template></el-table-column><el-table-column label="状态 / 指标" min-width="120"><template #default="{row}">{{ row.training_status||row.status||'未提供' }}<small class="browse-secondary">版本 mAP50：{{ shownValue(row.map50??row.metrics?.map50??row.metrics?.mAP50) }}</small><small class="browse-secondary">Test mAP50：{{ shownValue(row.test_metrics?.map50??row.test_metrics?.mAP50) }}</small></template></el-table-column><el-table-column label="操作" width="125"><template #default="{row}"><el-button link type="primary" :aria-label="`查看版本${row.id}详情`" @click="show(row)">详情</el-button><el-button link :aria-label="`查看版本${row.id}转换历史`" @click="history(row)">转换记录</el-button><el-button v-if="row.training_job_id&&context.openReport" link @click="reportVersion(row)">训练报告</el-button><el-button v-if="row.training_job_id&&context.openTasks" link @click="context.openTasks(row.training_job_id)">训练任务</el-button></template></el-table-column></el-table>
  <footer v-if="versions" class="preview-pagination"><span>共 {{ versions.total }} 个版本</span><el-pagination layout="prev, pager, next" :pager-count="5" :page-size="20" :total="versions.total" :current-page="versions.page" @current-change="changeVersionPage"/></footer>
 </section></div>
 <el-drawer v-if="editor" :model-value="true" :title="editingId?'算法详情与基本编辑':'新增本地算法'" size="min(620px, 100vw)" :append-to-body="false" :lock-scroll="false" :before-close="closeEditor"><AlgorithmEditor :context="context" :algorithm-id="editingId" @close="closeEditor" @saved="saved"/></el-drawer>
 <el-drawer :model-value="drawer" title="模型版本详情" size="min(680px, 100vw)" :append-to-body="false" :lock-scroll="false" :before-close="closeDetail"><el-skeleton v-if="reads.busy.detail" :rows="8" animated/><el-alert v-else-if="reads.errors.detail" :title="reads.errors.detail" type="error" :closable="false"/><ModelVersionDetails v-else-if="detail" :detail="detail"/><template #footer><el-button @click="closeDetail">关闭版本详情</el-button><el-button v-if="detail" @click="context.openLegacy({algorithmId:selected,versionId:detail.version.id})">原版本转换 / 验证</el-button><el-button v-if="detail" type="primary" @click="history(detail.version)">查看转换历史</el-button></template></el-drawer>
</section></template>
